def equipment_caption(fn):
    f = fn.lower()
    if 'dallah' in f and 'silver' in f: return 'دلة فضية'
    if 'dallah' in f or 'coffee-pot' in f: return 'دلة ذهبية'
    if 'stand' in f: return 'استاند فناجين ذهبي'
    if 'tray' in f: return 'صينية تقديم ذهبية'
    if 'mug' in f: return 'كوب قهوة بالشعار'
    if 'goblet' in f: return 'كأس زجاجي بساق'
    if 'tea' in f and ('glass' in f or 'ribbed' in f): return 'كاسة شاي زجاجية'
    if 'tea' in f: return 'كاسة شاي وصحن'
    if 'gahwa' in f or 'qahwa' in f or 'coffee' in f: return 'فنجان قهوة'
    if 'cup' in f: return 'فنجان وصحن'
    return 'معدات تقديم'
